/* From Uiverse.io by 3bdel3ziz-T  - Tags: material design, animation, checkbox, hamburger, menu, click effect, click animation, close */
.__UIV_SCOPE__ .burger {
  width: 40px;
  height: 40px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  user-select: none;
  cursor: pointer;
  transition: 300ms;
  border-radius: 10px;
}
.__UIV_SCOPE__ .burger input[type="checkbox"] {
  appearance: none;
  transition: 300ms;
}

.__UIV_SCOPE__ .burger::before,
.__UIV_SCOPE__ .burger::after {
  content: "";
  transition: 300ms;
  transform-origin: center center;
}

.__UIV_SCOPE__ .burger::before {
  transform: translateY(8px);
}
.__UIV_SCOPE__ .burger::after {
  transform: translateY(-8px);
}
.__UIV_SCOPE__ .burger .line,
.__UIV_SCOPE__ .burger::before,
.__UIV_SCOPE__ .burger::after {
  width: 25px;
  height: 2.1px;
  display: block;
  background-color: black;
  border-radius: 5px;
  position: absolute;
}

.__UIV_SCOPE__ .burger .line:checked {
  width: 0;
  transition-delay: 100ms;
}
.__UIV_SCOPE__ .burger:has(.line:checked)::before {
  animation: animation1 400ms ease-out 0s 1 both;
}
.__UIV_SCOPE__ .burger:has(.line:checked)::after {
  animation: animation2 400ms ease-out 0s 1 both;
}

.__UIV_SCOPE__ .burger:hover {
  background: #aeaeae;
  border-radius: 50%;
}

.__UIV_SCOPE__ .burger:hover .line,
.__UIV_SCOPE__ .burger:hover::before,
.__UIV_SCOPE__ .burger:hover::after {
  background: #e8e8e8;
}

.__UIV_SCOPE__ .burger:active {
  scale: 0.95;
}
@keyframes animation1 {
  0% {
    transform: translateY(8px) rotate(0deg);
  }
  50% {
    transform: translateY(0px) rotate(0deg);
  }
  100% {
    transform: translateY(0px) rotate(45deg);
  }
}
@keyframes animation2 {
  0% {
    transform: translateY(-8px) rotate(0deg);
  }
  50% {
    transform: translateY(0px) rotate(0deg);
  }
  100% {
    transform: translateY(0px) rotate(-45deg);
  }
}
